describe('Public Profile Page', () => {
  const testUserId = 'test-user-123';
  const testUsername = 'testuser';
  const profileUrl = `/profile/${testUserId}`;

  beforeEach(() => {
    cy.visit(profileUrl);
  });

  it('should display public profile with shared user information', () => {
    // Verify profile page loads successfully
    cy.get('[data-testid="profile-container"]').should('be.visible');

    // Verify user information is displayed
    cy.get('[data-testid="profile-username"]')
      .should('be.visible')
      .and('contain', testUsername);

    cy.get('[data-testid="profile-avatar"]')
      .should('be.visible')
      .and('have.attr', 'src')
      .and('not.be.empty');

    // Verify shared profile sections are visible
    cy.get('[data-testid="profile-bio"]')
      .should('be.visible')
      .and('not.be.empty');

    cy.get('[data-testid="profile-location"]')
      .should('be.visible');

    cy.get('[data-testid="profile-join-date"]')
      .should('be.visible')
      .and('contain', 'Joined');

    // Verify public statistics are displayed
    cy.get('[data-testid="profile-followers-count"]')
      .should('be.visible')
      .and('match', /^\d+$/);

    cy.get('[data-testid="profile-following-count"]')
      .should('be.visible')
      .and('match', /^\d+$/);

    // Verify action buttons are present
    cy.get('[data-testid="follow-button"]')
      .should('be.visible')
      .and('not.be.disabled');

    cy.get('[data-testid="message-button"]')
      .should('be.visible')
      .and('not.be.disabled');
  });

  it('should not display private information on public profile', () => {
    // Verify sensitive information is not visible
    cy.get('[data-testid="profile-email"]').should('not.exist');
    cy.get('[data-testid="profile-phone"]').should('not.exist');
    cy.get('[data-testid="profile-private-notes"]').should('not.exist');

    // Verify edit profile button is not visible for other users
    cy.get('[data-testid="edit-profile-button"]').should('not.exist');

    // Verify settings button is not visible
    cy.get('[data-testid="profile-settings-button"]').should('not.exist');
  });

  it('should handle profile not found gracefully', () => {
    cy.visit('/profile/nonexistent-user-id');

    cy.get('[data-testid="profile-not-found"]')
      .should('be.visible')
      .and('contain', 'Profile not found');

    cy.get('[data-testid="back-to-home-button"]')
      .should('be.visible')
      .click();

    cy.url().should('eq', Cypress.config().baseUrl + '/');
  });

  it('should display user activity feed on public profile', () => {
    cy.get('[data-testid="activity-feed"]')
      .should('be.visible');

    cy.get('[data-testid="activity-item"]')
      .should('have.length.greaterThan', 0);

    cy.get('[data-testid="activity-item"]').first()
      .should('contain', 'posted')
      .or('contain', 'liked')
      .or('contain', 'followed');
  });

  it('should load profile data correctly when visiting via direct URL', () => {
    cy.request('GET', profileUrl).then((response) => {
      expect(response.status).to.equal(200);
    });

    cy.get('[data-testid="profile-username"]')
      .should('be.visible')
      .invoke('text')
      .then((text) => {
        expect(text).to.equal(testUsername);
      });
  });

  it('should handle network errors gracefully', () => {
    cy.intercept('GET', `/api/profile/${testUserId}`, { forceNetworkError: true });

    cy.visit(profileUrl);

    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', 'Unable to load profile');

    cy.get('[data-testid="retry-button"]')
      .should('be.visible')
      .click();

    cy.get('[data-testid="profile-container"]')
      .should('be.visible');
  });
});
